#!/usr/bin/env bash
# One-click installer for Lokinya's build of WayVR: downloads the newest AppImage from the
# GitHub releases into ~/Applications (an older copy is kept as .bak).
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/wayvr/lokinya-build/get.sh | bash
# Add example watch buttons (Discord mute, …) too:
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/wayvr/lokinya-build/get.sh | bash -s -- --buttons
# Remove:  … | bash -s -- --uninstall
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). GPL-3.0.
set -euo pipefail
REPO="lokinyauv-create/wayvr"
ASSET="WayVR-lokinya-x86_64.AppImage"
DEST="$HOME/Applications/$ASSET"
BUTTONS="${XDG_CONFIG_HOME:-$HOME/.config}/wayvr/watch-buttons"

if [ "${1:-}" = "--uninstall" ]; then
	rm -f "$DEST"
	echo "Removed $DEST (settings in ~/.config/wayvr are kept). / Видалено."
	exit 0
fi

mkdir -p "$HOME/Applications"
echo "Downloading WayVR (Lokinya's build)… / Завантажую WayVR (збірка Lokinya)…"
TMP="$(mktemp "$HOME/Applications/.wayvr-XXXXXX")"; trap 'rm -f "$TMP"' EXIT
curl -fL --progress-bar "https://github.com/$REPO/releases/latest/download/$ASSET" -o "$TMP"
chmod 755 "$TMP"
[ -f "$DEST" ] && mv -f "$DEST" "$DEST.bak"   # a running AppImage can't be overwritten
mv "$TMP" "$DEST"
trap - EXIT
echo "Installed: $DEST / Встановлено."

if [ "${1:-}" = "--buttons" ]; then
	T="$(mktemp -d)"
	curl -fsSL "https://codeload.github.com/$REPO/tar.gz/refs/heads/lokinya-build" |
		tar -xz -C "$T" --strip-components=3 --wildcards '*/contrib/watch-buttons'
	mkdir -p "$BUTTONS"
	cp -n "$T"/* "$BUTTONS"/ 2>/dev/null || true
	rm -rf "$T"
	echo "Example watch buttons copied to $BUTTONS (see README there). / Приклади кнопок скопійовано."
fi
echo "Start: $DEST --openvr --show   (or let SteamVR / VR Auto Launcher start it)"
